'use client'
import { useState } from 'react'

export default function CodeBlock({ lang, code }) {
  const [copied, setCopied] = useState(false)

  const copy = async () => {
    try { await navigator.clipboard.writeText(code) } catch (_) {}
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return (
    <div style={{
      borderRadius: '10px', overflow: 'hidden',
      margin: '10px 0', border: '1px solid rgba(124,58,237,0.3)'
    }}>
      <div style={{
        display: 'flex', alignItems: 'center',
        justifyContent: 'space-between',
        padding: '6px 14px',
        background: 'rgba(124,58,237,0.12)',
        borderBottom: '1px solid rgba(124,58,237,0.18)'
      }}>
        <span style={{
          fontSize: '11px', color: '#a78bfa',
          fontFamily: 'Space Mono, monospace',
          fontWeight: 700, letterSpacing: '0.06em'
        }}>
          {lang || 'code'}
        </span>
        <button onClick={copy} style={{
          background: 'none',
          border: `1px solid ${copied ? '#10b981' : 'rgba(124,58,237,0.3)'}`,
          color: copied ? '#10b981' : '#475569',
          cursor: 'pointer', fontSize: '11px',
          padding: '2px 10px', borderRadius: '20px',
          fontFamily: 'inherit', transition: 'all 0.2s'
        }}>
          {copied ? '✓ copied' : 'copy'}
        </button>
      </div>
      <pre style={{
        margin: 0, padding: '14px 16px',
        fontSize: '13px', lineHeight: '1.7',
        color: '#e2e8f0', background: '#07070f',
        fontFamily: 'Space Mono, Consolas, monospace',
        overflowX: 'auto', whiteSpace: 'pre'
      }}>
        <code>{code}</code>
      </pre>
    </div>
  )
}