'use client'
import { useState, useRef, useEffect, useCallback } from 'react'
import MessageContent from '../components/MessageContent'
import { uid, formatTime, truncate, SUGGESTIONS } from '../lib/utils'

function TypingDots() {
  return (
    <div style={{ display:'flex', gap:'5px', alignItems:'center', height:'24px' }}>
      {[0,1,2].map(i => (
        <span key={i} style={{
          display:'inline-block', width:'7px', height:'7px',
          borderRadius:'50%', background:'#7c3aed',
          animation:`dot 0.9s ease-in-out ${i*0.18}s infinite`
        }}/>
      ))}
    </div>
  )
}

function Message({ msg, streaming, streamText }) {
  const isUser = msg.role === 'user'
  const text   = streaming ? streamText : msg.content
  return (
    <div style={{
      display:'flex', gap:'14px', padding:'20px',
      borderBottom:'1px solid rgba(255,255,255,0.025)',
      background: isUser ? 'transparent' : 'rgba(124,58,237,0.03)',
      animation:'fadeUp 0.25s ease'
    }}>
      <div style={{
        width:'30px', height:'30px', borderRadius:'9px', flexShrink:0,
        background: isUser ? 'linear-gradient(135deg,#1e3a8a,#1d4ed8)' : 'linear-gradient(135deg,#7c3aed,#4f46e5)',
        display:'flex', alignItems:'center', justifyContent:'center',
        fontSize:'11px', fontWeight:700, color:'#fff', marginTop:'1px',
        fontFamily:'Space Mono, monospace'
      }}>
        {isUser ? 'U' : 'V'}
      </div>
      <div style={{ flex:1, minWidth:0, maxWidth:'760px' }}>
        <div style={{ display:'flex', alignItems:'center', gap:'8px', marginBottom:'8px' }}>
          <span style={{ fontSize:'13px', fontWeight:600, color: isUser ? '#93c5fd' : '#c4b5fd' }}>
            {isUser ? 'You' : 'VIGIL'}
          </span>
          {!streaming && (
            <span style={{ fontSize:'10.5px', color:'#475569' }}>{formatTime(msg.at)}</span>
          )}
        </div>
        {streaming && !streamText
          ? <TypingDots />
          : <>
              <MessageContent text={text} />
              {streaming && (
                <span style={{
                  display:'inline-block', width:'2px', height:'16px',
                  background:'#a78bfa', marginLeft:'2px',
                  verticalAlign:'text-bottom',
                  animation:'blink 0.9s step-end infinite'
                }}/>
              )}
            </>
        }
      </div>
    </div>
  )
}

function EmptyState({ onSend }) {
  const [hov, setHov] = useState(null)
  return (
    <div style={{
      display:'flex', flexDirection:'column', alignItems:'center',
      justifyContent:'center', minHeight:'70vh', padding:'40px 24px',
      textAlign:'center', animation:'fadeIn 0.4s ease'
    }}>
      <div style={{
        width:'64px', height:'64px',
        background:'rgba(124,58,237,0.08)',
        border:'1px solid rgba(124,58,237,0.3)',
        borderRadius:'20px', display:'flex',
        alignItems:'center', justifyContent:'center',
        marginBottom:'20px', fontSize:'28px'
      }}>⚡</div>
      <h1 style={{ fontSize:'24px', fontWeight:600, color:'#f1f5f9', marginBottom:'8px', letterSpacing:'-0.02em' }}>
        What can I help with?
      </h1>
      <p style={{ fontSize:'14px', color:'#475569', maxWidth:'360px', lineHeight:'1.65', marginBottom:'32px' }}>
        VIGIL is ready. Ask anything — code, ideas, writing, explanations.
      </p>
      <div style={{ display:'grid', gridTemplateColumns:'repeat(2,minmax(0,1fr))', gap:'10px', maxWidth:'560px', width:'100%' }}>
        {SUGGESTIONS.map((s,i) => (
          <button key={i} onClick={() => onSend(s.text)}
            onMouseEnter={() => setHov(i)}
            onMouseLeave={() => setHov(null)}
            style={{
              padding:'14px 16px',
              background: hov===i ? 'rgba(124,58,237,0.14)' : 'rgba(124,58,237,0.06)',
              border:`1px solid ${hov===i ? 'rgba(124,58,237,0.45)' : 'rgba(124,58,237,0.18)'}`,
              borderRadius:'10px', cursor:'pointer', fontSize:'13px',
              textAlign:'left', color: hov===i ? '#c4b5fd' : '#94a3b8',
              fontFamily:'inherit', lineHeight:'1.55',
              display:'flex', alignItems:'flex-start', gap:'10px',
              transition:'all 0.15s',
              transform: hov===i ? 'translateY(-1px)' : 'none'
            }}>
            <span style={{ fontSize:'16px', lineHeight:'1.4', flexShrink:0 }}>{s.icon}</span>
            <span>{s.text}</span>
          </button>
        ))}
      </div>
    </div>
  )
}

function Sidebar({ convs, activeId, onNew, onSelect, onDelete }) {
  const [hov, setHov] = useState(null)
  return (
    <aside style={{
      width:'240px', minWidth:'240px', background:'#0d0d1a',
      borderRight:'1px solid rgba(124,58,237,0.18)',
      display:'flex', flexDirection:'column', height:'100%', overflow:'hidden'
    }}>
      <div style={{ padding:'18px 16px 16px', borderBottom:'1px solid rgba(124,58,237,0.18)', flexShrink:0 }}>
        <div style={{ display:'flex', alignItems:'center', gap:'10px' }}>
          <div style={{
            width:'32px', height:'32px', borderRadius:'9px',
            background:'linear-gradient(135deg,#7c3aed,#4f46e5)',
            display:'flex', alignItems:'center', justifyContent:'center',
            fontFamily:'Space Mono,monospace', fontWeight:700, fontSize:'15px', color:'#fff', flexShrink:0
          }}>V</div>
          <div>
            <div style={{ fontFamily:'Space Mono,monospace', fontWeight:700, fontSize:'13.5px', letterSpacing:'0.1em', color:'#f1f5f9' }}>VIGIL</div>
            <div style={{ fontSize:'9px', color:'#475569', letterSpacing:'0.15em' }}>AI ASSISTANT</div>
          </div>
        </div>
      </div>
      <div style={{ padding:'12px', flexShrink:0 }}>
        <button onClick={onNew}
          onMouseEnter={e=>e.currentTarget.style.background='rgba(124,58,237,0.2)'}
          onMouseLeave={e=>e.currentTarget.style.background='rgba(124,58,237,0.1)'}
          style={{
            width:'100%', padding:'9px 13px',
            background:'rgba(124,58,237,0.1)',
            border:'1px solid rgba(124,58,237,0.3)',
            borderRadius:'10px', color:'#a78bfa', cursor:'pointer',
            fontSize:'13px', fontWeight:500, fontFamily:'inherit',
            display:'flex', alignItems:'center', gap:'8px', transition:'all 0.15s'
          }}>
          <span style={{ fontSize:'17px', lineHeight:1 }}>＋</span> New conversation
        </button>
      </div>
      <div style={{ flex:1, overflowY:'auto', padding:'4px 8px' }}>
        {convs.length === 0 && (
          <div style={{ padding:'30px 12px', textAlign:'center', color:'#475569', fontSize:'12px', lineHeight:'1.8' }}>
            <div style={{ fontSize:'24px', marginBottom:'8px', opacity:.4 }}>💬</div>
            No conversations yet.
          </div>
        )}
        {convs.map(c => (
          <div key={c.id}
            onClick={() => onSelect(c.id)}
            onMouseEnter={() => setHov(c.id)}
            onMouseLeave={() => setHov(null)}
            style={{
              display:'flex', alignItems:'center', gap:'8px',
              padding:'8px', borderRadius:'6px', cursor:'pointer', marginBottom:'1px',
              background: c.id===activeId ? 'rgba(124,58,237,0.12)' : hov===c.id ? 'rgba(255,255,255,0.04)' : 'transparent',
              border:`1px solid ${c.id===activeId ? 'rgba(124,58,237,0.3)' : 'transparent'}`,
              transition:'all 0.12s'
            }}>
            <span style={{ fontSize:'12px', opacity:.5, flexShrink:0 }}>💬</span>
            <span style={{ flex:1, fontSize:'12.5px', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap', color: c.id===activeId ? '#c4b5fd' : '#94a3b8' }}>
              {truncate(c.title, 30)}
            </span>
            <button
              onClick={e => { e.stopPropagation(); onDelete(c.id) }}
              onMouseEnter={e => { e.target.style.color='#ef4444' }}
              onMouseLeave={e => { e.target.style.color='#475569' }}
              style={{ background:'none', border:'none', color:'#475569', cursor:'pointer', fontSize:'11px', padding:'1px 4px', opacity: hov===c.id ? 1 : 0, transition:'all 0.12s' }}>
              ✕
            </button>
          </div>
        ))}
      </div>
      <div style={{ padding:'10px 16px', borderTop:'1px solid rgba(124,58,237,0.18)', fontSize:'11px', color:'#475569', display:'flex', alignItems:'center', gap:'6px', flexShrink:0 }}>
        <div style={{ width:'6px', height:'6px', borderRadius:'50%', background:'#10b981', animation:'pulse 2s ease-in-out infinite' }}/>
        llama-3.3-70b · free
      </div>
    </aside>
  )
}

export default function Home() {
  const [convs,      setConvs]   = useState([])
  const [activeId,   setActiveId]= useState(null)
  const [input,      setInput]   = useState('')
  const [busy,       setBusy]    = useState(false)
  const [streamText, setStream]  = useState('')
  const [sidebarOn,  setSidebar] = useState(true)

  const endRef   = useRef(null)
  const taRef    = useRef(null)
  const abortRef = useRef(null)

  const active = convs.find(c => c.id === activeId)
  const msgs   = active?.messages || []

  useEffect(() => { endRef.current?.scrollIntoView({ behavior:'smooth' }) }, [msgs, streamText])

  useEffect(() => {
    if (taRef.current) {
      taRef.current.style.height = 'auto'
      taRef.current.style.height = Math.min(taRef.current.scrollHeight, 200) + 'px'
    }
  }, [input])

  const newConv = useCallback(() => {
    const id = uid()
    setConvs(p => [{ id, title:'New conversation', messages:[], at:new Date() }, ...p])
    setActiveId(id)
    setInput('')
  }, [])

  const deleteConv = useCallback(id => {
    setConvs(p => p.filter(c => c.id !== id))
    if (activeId === id) setActiveId(null)
  }, [activeId])

  const send = useCallback(async (override) => {
    const text = (override || input).trim()
    if (!text || busy) return
    setInput(''); setBusy(true); setStream('')

    let cid = activeId, prevMsgs = active?.messages || []
    if (!cid) {
      cid = uid(); prevMsgs = []
      const title = text.length > 46 ? text.slice(0,46)+'…' : text
      setConvs(p => [{ id:cid, title, messages:[], at:new Date() }, ...p])
      setActiveId(cid)
    }

    const userMsg  = { role:'user', content:text, id:uid(), at:new Date() }
    const nextMsgs = [...prevMsgs, userMsg]
    setConvs(p => p.map(c => c.id===cid ? {
      ...c,
      title: prevMsgs.length===0 ? (text.length>46 ? text.slice(0,46)+'…' : text) : c.title,
      messages: nextMsgs
    } : c))

    abortRef.current = new AbortController()
    let accumulated  = ''

    try {
      const res = await fetch('/api/chat', {
        method:'POST', headers:{ 'Content-Type':'application/json' },
        body: JSON.stringify({ messages: nextMsgs }),
        signal: abortRef.current.signal,
      })
      if (!res.ok) throw new Error(`API error ${res.status}`)
      const reader  = res.body.getReader()
      const decoder = new TextDecoder()
      while (true) {
        const { done, value } = await reader.read()
        if (done) break
        const lines = decoder.decode(value, { stream:true }).split('\n')
        for (const line of lines) {
          if (!line.startsWith('data: ')) continue
          const data = line.slice(6).trim()
          if (data === '[DONE]') break
          try {
            const parsed = JSON.parse(data)
            if (parsed.text) { accumulated += parsed.text; setStream(accumulated) }
          } catch (_) {}
        }
      }
    } catch (err) {
      if (err.name !== 'AbortError') { accumulated = `Error: ${err.message}`; setStream(accumulated) }
    }

    setConvs(p => p.map(c => c.id===cid ? { ...c, messages:[...nextMsgs, { role:'assistant', content:accumulated||'(no response)', id:uid(), at:new Date() }] } : c))
    setStream(''); setBusy(false)
  }, [input, busy, activeId, active])

  const onKey = e => { if (e.key==='Enter' && !e.shiftKey) { e.preventDefault(); send() } }
  const canSend = input.trim().length > 0 && !busy

  return (
    <div style={{ display:'flex', height:'100dvh', background:'#07070f', overflow:'hidden' }}>
      <div style={{ width:sidebarOn?'240px':'0', minWidth:sidebarOn?'240px':'0', overflow:'hidden', transition:'all 0.22s ease', flexShrink:0 }}>
        <Sidebar convs={convs} activeId={activeId} onNew={newConv} onSelect={setActiveId} onDelete={deleteConv} />
      </div>
      <div style={{ flex:1, display:'flex', flexDirection:'column', overflow:'hidden', minWidth:0 }}>
        <header style={{ height:'52px', borderBottom:'1px solid rgba(124,58,237,0.18)', display:'flex', alignItems:'center', padding:'0 18px', gap:'12px', background:'rgba(13,13,26,0.95)', flexShrink:0 }}>
          <button onClick={() => setSidebar(!sidebarOn)}
            onMouseEnter={e=>e.target.style.color='#f1f5f9'}
            onMouseLeave={e=>e.target.style.color='#475569'}
            style={{ background:'none', border:'none', color:'#475569', cursor:'pointer', padding:'6px', borderRadius:'6px', fontSize:'18px', lineHeight:1 }}>☰</button>
          {!sidebarOn && (
            <div style={{ display:'flex', alignItems:'center', gap:'7px', flexShrink:0 }}>
              <div style={{ width:'26px', height:'26px', borderRadius:'7px', background:'linear-gradient(135deg,#7c3aed,#4f46e5)', display:'flex', alignItems:'center', justifyContent:'center', fontFamily:'Space Mono,monospace', fontWeight:700, fontSize:'12px', color:'#fff' }}>V</div>
              <span style={{ fontFamily:'Space Mono,monospace', fontWeight:700, fontSize:'13px', letterSpacing:'0.08em' }}>VIGIL</span>
            </div>
          )}
          <div style={{ flex:1, display:'flex', justifyContent:'center' }}>
            {active && <span style={{ fontSize:'13px', color:'#475569', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap', maxWidth:'400px' }}>{active.title}</span>}
          </div>
          <div style={{ display:'flex', alignItems:'center', gap:'10px', flexShrink:0 }}>
            {busy && <button onClick={() => abortRef.current?.abort()} style={{ background:'none', border:'1px solid rgba(239,68,68,0.3)', color:'#ef4444', cursor:'pointer', fontSize:'11.5px', padding:'4px 12px', borderRadius:'20px', fontFamily:'inherit' }}>◼ Stop</button>}
            <div style={{ display:'flex', alignItems:'center', gap:'5px', padding:'3px 10px', background:'rgba(16,185,129,0.1)', border:'1px solid rgba(16,185,129,0.25)', borderRadius:'20px' }}>
              <div style={{ width:'5px', height:'5px', borderRadius:'50%', background:'#10b981', animation:'pulse 2s ease-in-out infinite' }}/>
              <span style={{ fontSize:'10.5px', color:'#10b981', letterSpacing:'0.06em', fontWeight:600 }}>LIVE</span>
            </div>
          </div>
        </header>
        <div style={{ flex:1, overflowY:'auto' }}>
          {msgs.length===0 && !busy && <EmptyState onSend={send} />}
          {msgs.map(msg => <Message key={msg.id} msg={msg} streaming={false} streamText="" />)}
          {busy && <Message msg={{ role:'assistant', content:'', id:'__stream__', at:new Date() }} streaming={true} streamText={streamText} />}
          <div ref={endRef} style={{ height:'20px' }} />
        </div>
        <div style={{ padding:'12px 20px 20px', background:'#07070f', borderTop:'1px solid rgba(124,58,237,0.18)', flexShrink:0 }}>
          <div style={{ maxWidth:'760px', margin:'0 auto' }}>
            <div style={{ display:'flex', alignItems:'flex-end', gap:'10px', background:'#0d0d1a', border:'1px solid rgba(124,58,237,0.3)', borderRadius:'14px', padding:'10px 12px' }}>
              <textarea ref={taRef} value={input}
                onChange={e => setInput(e.target.value)}
                onKeyDown={onKey}
                placeholder="Message VIGIL…"
                disabled={busy} rows={1}
                style={{ flex:1, background:'none', border:'none', outline:'none', color:'#f1f5f9', fontSize:'14.5px', lineHeight:'1.65', resize:'none', fontFamily:'inherit', padding:0, maxHeight:'200px', overflowY:'auto', opacity:busy?0.5:1 }}
              />
              <button onClick={() => send()} disabled={!canSend} style={{
                width:'36px', height:'36px', flexShrink:0, border:'none', borderRadius:'10px',
                cursor:canSend?'pointer':'not-allowed',
                background:canSend?'linear-gradient(135deg,#7c3aed,#4f46e5)':'rgba(124,58,237,0.1)',
                color:'#fff', display:'flex', alignItems:'center', justifyContent:'center', fontSize:'16px', transition:'all 0.18s'
              }}>
                {busy
                  ? <span style={{ width:'14px', height:'14px', border:'2px solid rgba(255,255,255,0.25)', borderTopColor:'#fff', borderRadius:'50%', display:'block', animation:'spin 0.7s linear infinite' }}/>
                  : '↑'}
              </button>
            </div>
            <div style={{ textAlign:'center', marginTop:'8px', fontSize:'11px', color:'rgba(71,85,105,0.6)' }}>
              VIGIL · built from scratch · free forever
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}