'use client'
import CodeBlock from './CodeBlock'
import { parseContent, parseBold } from '../lib/utils'

function TextLine({ text }) {
  const segs = parseBold(text)
  return (
    <>
      {segs.map((s, i) =>
        s.bold
          ? <strong key={i} style={{ fontWeight: 600, color: '#c4b5fd' }}>{s.text}</strong>
          : <span key={i}>{s.text}</span>
      )}
    </>
  )
}

function TextBlock({ value }) {
  const lines = value.split('\n')
  const out   = []
  let   para  = []

  const flush = () => {
    if (!para.length) return
    out.push(
      <p key={out.length} style={{ margin: '0 0 10px', lineHeight: '1.8', color: '#f1f5f9', fontSize: '14.5px' }}>
        {para.map((l, i) => <span key={i}>{i > 0 && <br />}<TextLine text={l} /></span>)}
      </p>
    )
    para = []
  }

  for (const line of lines) {
    if (!line.trim()) {
      flush()
    } else if (/^#{1,3}\s/.test(line)) {
      flush()
      out.push(
        <p key={out.length} style={{ fontSize: '16px', fontWeight: 600, color: '#f1f5f9', margin: '14px 0 6px', paddingBottom: '4px', borderBottom: '1px solid rgba(124,58,237,0.18)' }}>
          <TextLine text={line.replace(/^#{1,3}\s/, '')} />
        </p>
      )
    } else if (/^\d+\.\s/.test(line)) {
      flush()
      out.push(
        <p key={out.length} style={{ margin: '3px 0', paddingLeft: '20px', lineHeight: '1.75', color: '#f1f5f9', fontSize: '14.5px' }}>
          <TextLine text={line} />
        </p>
      )
    } else if (/^[-•]\s/.test(line)) {
      flush()
      out.push(
        <p key={out.length} style={{ margin: '3px 0', paddingLeft: '20px', lineHeight: '1.75', color: '#f1f5f9', fontSize: '14.5px', position: 'relative' }}>
          <span style={{ position: 'absolute', left: '6px', color: '#7c3aed', fontWeight: 700 }}>›</span>
          <TextLine text={line.replace(/^[-•]\s/, '')} />
        </p>
      )
    } else {
      para.push(line)
    }
  }
  flush()
  return <>{out}</>
}

export default function MessageContent({ text }) {
  const parts = parseContent(text)
  return (
    <div style={{ minWidth: 0 }}>
      {parts.map((p, i) =>
        p.type === 'code'
          ? <CodeBlock key={i} lang={p.lang} code={p.value} />
          : <TextBlock key={i} value={p.value} />
      )}
    </div>
  )
}